preConditionHook:
// FADE THE TEST OF THE WEDGE'S EXTREME. After a three-push pattern, price comes
// back to within a tolerance of the pattern's own extreme WITHOUT exceeding
// it, and the next bar reverses away from it: the double-top test of a wedge
// high is a short, the double-bottom test of a wedge low a buy.
//
// T21-78 gives the mechanizable form -- a test of the extreme within a band
// followed by a close beyond the prior bar's opposite extreme -- and R03-05 the same
// trade in words. R03-05's tolerance was 2 ticks; T21-78's 0.1 ATR is kept as
// the default because the engine exposes no tick size to strategies, so a tick
// threshold cannot be converted -- the same substitution BreakoutLevelRetest
// and PriorSessionLevelTest make. The general double-top machinery lives in
// swing_structure; this rule is the version anchored on the three-push
// extreme.
//
// THE TEST BAR IS THE PRIOR BAR, and the extreme is a CONFIRMED pivot, so it
// is at least swingStrength bars old -- at swingStrength >= 2 the prior bar
// can never be the pivot bar itself. At swingStrength 1 it can, and the test
// degenerates to the pivot touching itself; the grid should keep
// swingStrength >= 2.
//
// WFSafe_AvgTrueRange, not the built-in: MultiWalk's override is a DIFFERENT
// function -- a ROLLING accumulator, seeded with a full sum on the first
// calculated bar or when the length changes, and updated thereafter as TWO
// statements, because EL evaluates S[1] + in - out left to right and folding
// it to S += in - out rounds differently. Ported from AtrProfitTarget, the
// reference. One call site, here in the hook, so exactly one accumulator
// advances per bar.
//
// Pivot scan as in ThreePushPattern, inlined; the register lists Occurrence 3+
// as unmeasured, so the third push is found by hand. MEASURED
// (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60 min): the pivot bar is AT
// OR ABOVE the swingStrength OLDER bars and STRICTLY ABOVE the swingStrength
// NEWER bars -- bars-ago indexing, so the newer bars are the smaller k and
// take el_gt / el_lt, the older el_ge / el_le; confirmation lag exactly
// swingStrength bars; candidate offsets swingStrength .. lookbackBars - 1, the
// neighbourhood reaching swingStrength bars past the window, so the deepest
// bar the scan touches is lookbackBars - 1 + swingStrength. No early break.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivStrength = (int)swingStrength;
pivWindow = (int)lookbackBars;
nHiPiv = 0;
nLoPiv = 0;
hiPx1 = -1.0;
hiPx2 = -1.0;
hiPx3 = -1.0;
loPx1 = -1.0;
loPx2 = -1.0;
loPx3 = -1.0;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) hiPx1 = high[j];
        if (nHiPiv == 2) hiPx2 = high[j];
        if (nHiPiv == 3) hiPx3 = high[j];
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) loPx1 = low[j];
        if (nLoPiv == 2) loPx2 = low[j];
        if (nLoPiv == 3) loPx3 = low[j];
    }
}
patUp = (nHiPiv == 3) && el_gt(hiPx1, hiPx2) && el_gt(hiPx2, hiPx3);
patDn = (nLoPiv == 3) && el_lt(loPx1, loPx2) && el_lt(loPx2, loPx3);
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
tol = tolAtr * atr;
fadeLong = patDn && el_ge(low[1], loPx1) && el_le(low[1], loPx1 + tol) && el_gt(close[0], high[1]);
fadeShort = patUp && el_le(high[1], hiPx1) && el_ge(high[1], hiPx1 - tol) && el_lt(close[0], low[1]);
